B4.3.11 RMI_PDEV_COMMUNICATE command
               Perform device communication associated with a PDEV.
               B4.3.11.1 Interface
               B4.3.11.1.1   Input values
        Name                 Register    Bits        Type                                  Description
        fid                  X0          63:0        UInt64                                FID, value 0xC4000175
        pdev_ptr             X1          63:0        Address                               PA of the PDEV
        data_ptr             X2          63:0        Address                               PA of the communication data structure
               B4.3.11.1.2   Context
               The RMI_PDEV_COMMUNICATE command operates on the following context.
        Name                 Type                       Value                                      Before   Description
        pdev                 RmmPdev                    PdevAt(pdev_ptr)                           false    PDEV
        pdev_state_pre       RmmPdevState               PdevAt(pdev_ptr).state                     true     PDEV previous state
        data                 RmiDevCommData             RmiDevCommDataAt(data_ptr)                 false    Device
                                                                                                            communication object
               B4.3.11.1.3   Output values
        Name                 Register    Bits        Type                                  Description
        result               X0          63:0        RmiCommandReturnCode                  Command return status
               B4.3.11.2 Failure conditions
  ID                          Condition
  da_supp                     pre: ImplFeatures().feat_da != FEATURE_TRUE
                              post: ResultEqual(result, RMI_ERROR_NOT_SUPPORTED)
  pdev_align                  pre: !AddrIsGranuleAligned(pdev_ptr)
                              post: ResultEqual(result, RMI_ERROR_INPUT)
  pdev_bound                  pre: !PaIsDelegable(pdev_ptr)
                              post: ResultEqual(result, RMI_ERROR_INPUT)
  pdev_gran_state             pre: GranuleAt(pdev_ptr).state != PDEV
                              post: ResultEqual(result, RMI_ERROR_INPUT)
  data_align                  pre: !AddrIsGranuleAligned(data_ptr)
                              post: ResultEqual(result, RMI_ERROR_INPUT)
  ID                            Condition
  data_pas                      pre: !GranuleAccessPermitted(data_ptr, PAS_NS)
                                post: ResultEqual(result, RMI_ERROR_INPUT)
  req_align                     pre: !AddrIsGranuleAligned(data.enter.req_addr)
                                post: ResultEqual(result, RMI_ERROR_INPUT)
  req_pas                       pre: !GranuleAccessPermitted(data.enter.req_addr, PAS_NS)
                                post: ResultEqual(result, RMI_ERROR_INPUT)
  resp_align                    pre: !AddrIsGranuleAligned(data.enter.resp_addr)
                                post: ResultEqual(result, RMI_ERROR_INPUT)
  resp_pas                      pre: !GranuleAccessPermitted(data.enter.resp_addr, PAS_NS)
                                post: ResultEqual(result, RMI_ERROR_INPUT)
  resp_len                      pre: data.enter.resp_len > RMM_GRANULE_SIZE
                                post: ResultEqual(result, RMI_ERROR_INPUT)
  comm_state                    pre:      (pdev.comm_state == DEV_COMM_IDLE
                                              || pdev.comm_state == DEV_COMM_ERROR)
                                post: ResultEqual(result, RMI_ERROR_DEVICE)
               B4.3.11.2.1     Failure condition ordering
               [da_supp] < [pdev_align, pdev_bound, pdev_gran_state, data_align,
                    data_pas, req_align, req_pas, resp_align, resp_pas, resp_len]
               [pdev_gran_state] < [comm_state]
                                                                                                                          da_supp
                                                                                                                  RMI_ERROR_NOT _SUPPORT ED
                    resp_len   resp_pas   resp_align   req_pas   req_align   data_pas   data_align   pdev_bound         pdev_align            pdev_gran_state
                                                                                                                                                    RMI_ERROR_INPUT
                                                                                                                                                comm_state
                                                                                                                                                RMI_ERROR_DEVICE
               B4.3.11.3 Success conditions
  ID                            Condition
  comm_state                    post: pdev.comm_state == DeviceCommunicate(pdev, data)
  error                         pre:  (DeviceCommunicate(pdev, data) == DEV_COMM_ERROR
                                          && pdev.state != PDEV_STOPPING)
                                post: pdev.state == PDEV_ERROR
  new                           pre:  (DeviceCommunicate(pdev, data) == DEV_COMM_IDLE
                                          && pdev_state_pre == PDEV_NEW)
                                post: pdev.state == PDEV_NEEDS_KEY
  has_key                       pre:  (DeviceCommunicate(pdev, data) == DEV_COMM_IDLE
                                          && pdev_state_pre == PDEV_HAS_KEY)
                                post: pdev.state == PDEV_READY
  ready                         pre:  (DeviceCommunicate(pdev, data) == DEV_COMM_IDLE
                                          && pdev_state_pre == PDEV_READY)
                                post: pdev.state == PDEV_READY
  ID                        Condition
  stopped                   pre:  (DeviceCommunicate(pdev, data) != DEV_COMM_ACTIVE
                                      && pdev_state_pre == PDEV_STOPPING)
                            post: pdev.state == PDEV_STOPPED
  communicating             pre:  (DeviceCommunicate(pdev, data) == DEV_COMM_IDLE
                                      && pdev_state_pre == PDEV_COMMUNICATING)
                            post: pdev.state == PDEV_READY
  ide_resetting             pre:  (DeviceCommunicate(pdev, data) == DEV_COMM_IDLE
                                      && pdev_state_pre == PDEV_IDE_RESETTING)
                            post: pdev.state == PDEV_READY
             B4.3.11.4 Footprint
    ID                        Value
    state                     pdev.state
    comm_state                pdev.comm_state

