  params_pas                       pre: !GranuleAccessPermitted(params_ptr, PAS_NS)
                                   post: ResultEqual(result, RMI_ERROR_INPUT)
  params_valid                     pre: !RmiPdevParamsIsValid(params_ptr)
                                   post: ResultEqual(result, RMI_ERROR_INPUT)
  flags_supp                       pre: !RmiPdevFlagsSupported(params.flags)
                                   post: ResultEqual(result, RMI_ERROR_INPUT)
  num_aux                          pre: params.num_aux != PdevAuxCount(params.flags)
                                   post: ResultEqual(result, RMI_ERROR_INPUT)
  aux_align                        pre: !AuxAligned32(params.aux, params.num_aux)
                                   post: ResultEqual(result, RMI_ERROR_INPUT)
  aux_alias                        pre: AuxAlias32(pdev_ptr, params.aux, params.num_aux)
                                   post: ResultEqual(result, RMI_ERROR_INPUT)
  aux_state                        pre:  !AuxStateEqual32(
