                                  post: ResultEqual(result, RMI_ERROR_INPUT)
  rtt_align                       pre: !AddrIsGranuleAligned(rtt)
                                  post: ResultEqual(result, RMI_ERROR_INPUT)
  rtt_bound                       pre: !PaIsDelegableDram(rtt)
                                  post: ResultEqual(result, RMI_ERROR_INPUT)
  rtt_state                       pre: GranuleAt(rtt).state != DELEGATED
                                  post: ResultEqual(result, RMI_ERROR_INPUT)
  rtt_bound2                      pre:  ((realm.feat_lpa2 == FEATURE_FALSE)
                                            && (UInt(rtt) >= 2^48))
                                  post: ResultEqual(result, RMI_ERROR_INPUT)
  rtt_walk                        pre: walk.level < level - 1
                                  post: ResultEqual(result, RMI_ERROR_RTT_AUX, walk.level)
