  rtt_state                 post: GranuleAt(rtt).state == RTT
  rtte_state                post: walk.rtte.state == TABLE
  rtte_addr                 post: walk.rtte.addr == rtt
  rtte_c_ripas              pre: AddrIsProtected(ipa, realm)
                            post: RttAllEntriesRipas(RttAt(rtt), unfold.ripas)
