B4.3.57 RMI_VDEV_MAP command
                Maps device memory.
                B4.3.57.1 Interface
                B4.3.57.1.1   Input values
        Name                  Register    Bits        Type                                  Description
        fid                   X0          63:0        UInt64                                FID, value 0xC4000172
        rd                    X1          63:0        Address                               PA of the RD for the target Realm
        vdev_ptr              X2          63:0        Address                               PA of the VDEV
        ipa                   X3          63:0        Address                               IPA at which the memory will be
                                                                                            mapped in the target Realm
        level                 X4          63:0        Int64                                 RTT level
        addr                  X5          63:0        Address                               PA of the target device memory
                B4.3.57.1.2   Context
                The RMI_VDEV_MAP command operates on the following context.
        Name                  Type                       Value                                      Before   Description
        realm                 RmmRealm                   RealmAt(rd)                                false    Realm
        vdev_pre              RmmVdev                    VdevAt(vdev_ptr)                           true     VDEV
        vdev                  RmmVdev                    VdevAt(vdev_ptr)                           false    VDEV
        walk                  RmmRttWalkResult           RttWalk(                                   false    RTT walk result
                                                             realm, ipa,
                                                             level,
                                                             RMM_RTT_TREE_PRIMARY)
        entry_idx             UInt64                     RttEntryIndex(                             false    RTTE index
                                                             ipa, walk.level)
        pa_top                Address                    ToAddress(                                 false    Top PA of Granules
                                                             UInt(addr)                                      whose state is
                                                             + RttLevelSize(level))                          modified
                B4.3.57.1.3   Output values
        Name                  Register    Bits        Type                                  Description
        result                X0          63:0        RmiCommandReturnCode                  Command return status
               B4.3.57.2 Failure conditions
  ID                                       Condition
  addr_align                               pre: !AddrIsGranuleAligned(addr)
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  addr_bound                               pre: !PaIsDelegableDevMem(addr)
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  addr_state                               pre:  !GranulesAllState(
                                                     addr, pa_top,
                                                     DELEGATED)
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  rd_align                                 pre: !AddrIsGranuleAligned(rd)
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  rd_bound                                 pre: !PaIsDelegable(rd)
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  rd_state                                 pre: GranuleAt(rd).state != RD
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  vdev_align                               pre: !AddrIsGranuleAligned(vdev_ptr)
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  vdev_bound                               pre: !PaIsDelegable(vdev_ptr)
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  vdev_gran_state                          pre: GranuleAt(vdev_ptr).state != VDEV
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  vdev_realm                               pre: vdev.realm != rd
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  level_bound                              pre:  (!RttLevelIsValid(realm, level)
                                                     || level < 2)
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  ipa_align                                pre: !AddrIsRttLevelAligned(ipa, level)
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  ipa_bound                                pre: !AddrIsProtected(ipa, realm)
                                           post: ResultEqual(result, RMI_ERROR_INPUT)
  rtt_walk                                 pre: walk.level < level
                                           post: ResultEqual(result, RMI_ERROR_RTT, walk.level)
  rtte_state                               pre: walk.rtte.state != UNASSIGNED
                                           post: ResultEqual(result, RMI_ERROR_RTT, walk.level)
               B4.3.57.2.1            Failure condition ordering
               [rd_bound, rd_state] < [rtt_walk, rtte_state]
               [vdev_bound, vdev_gran_state] < [vdev_realm]
               [level_bound, ipa_bound] < [rtt_walk, rtte_state]
                  ipa_align   vdev_align      rd_align   addr_state   addr_bound   addr_align   vdev_gran_state   vdev_bound   ipa_bound   level_bound   rd_state    rd_bound
                                                                                                                  vdev_realm                                                          rtte_state     rtt_walk
                                                                                                                                                                                                   RMI_ERROR_RT
                                                                                                                                                                    RMI_ERROR_INPUT
                B4.3.57.3 Success conditions
  ID                        Condition
  state                     post: GranulesAllState(
                                      addr, pa_top,
                                      DEV_MAPPED)
  rtte_state                post: walk.rtte.state == ASSIGNED_DEV
  rtte_addr                 post: walk.rtte.addr == addr
  rtte_attr_ncoh            pre: PaIsDelegableNonCohDevMem(addr)
                            post: walk.rtte.attr_prot == MEMATTR_NON_CACHEABLE
  rtte_attr_coh             pre: PaIsDelegableCohDevMem(addr)
                            post: walk.rtte.attr_prot == MEMATTR_PASSTHROUGH
  rtte_sh_ncoh              pre: PaIsDelegableNonCohDevMem(addr)
                            post: walk.rtte.sh == SHAREABILITY_OUTER
  rtte_sh_coh               pre: PaIsDelegableCohDevMem(addr)
                            post: walk.rtte.sh == SHAREABILITY_INNER
  num_map                   post: vdev.num_map == vdev_pre.num_map + (
                                      RttLevelSize(level) << RMM_GRANULE_SIZE_ORDER)
                B4.3.57.4 Footprint
    ID                        Value
    state                     State of all Granules in range [addr, pa_top)
    rtte                      RttEntryAt(RttAt(walk.rtt_addr), entry_idx)

